INSERT INTO "ObservatoryClaim"
("id","caseId","claimType","statement","constructId","epistemicStatus","verificationStatus","confidence","permissibleLanguage","contradictionNote","publicStatus","createdAt","updatedAt")
VALUES
('obs_claim_jal10_c01',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='josephus-allmond' LIMIT 1),'role_creation','Executive Order 14 created the Chief Energy Officer position within the Office of the Governor on 25 March 2026.','role_origin','primary_record','unreviewed',NULL,'A cabinet-level Virginia office created by Executive Order 14.','No pre-existing statutory independence or permanent tenure.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_jal10_c02',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='josephus-allmond' LIMIT 1),'jurisdictional_first','Spanberger appointed Allmond as the position inaugural holder.','firstness','corroborated','unreviewed',NULL,'Virginia first Chief Energy Officer.','No United States, worldwide or profession-wide firstness.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_jal10_c03',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='josephus-allmond' LIMIT 1),'role_authorship_boundary','The governor created the role through executive authority; reviewed records do not establish Allmond as its designer.','role_origin','primary_record','unreviewed',NULL,'Appointed to a newly created role.','No claim that Allmond invented, negotiated or personally built the role.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_jal10_c04',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='josephus-allmond' LIMIT 1),'authority_boundary','Executive Order 14 reserves the governor continuing and ultimate authority.','time_bounded_authority','primary_record','unreviewed',NULL,'Cabinet-level officer operating under gubernatorial authority.','No independent sovereignty or unilateral statewide control.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_jal10_c05',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='josephus-allmond' LIMIT 1),'coordination_role','The role coordinates affordability, reliability and clean-energy work across named governmental, regulatory and market institutions.','distributed_governance','primary_record','unreviewed',NULL,'Coordinates Virginia energy policy across named bodies.','No sole control of agencies, PJM, utilities, legislation or rates.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_jal10_c06',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='josephus-allmond' LIMIT 1),'distributed_labor','Louise White serves as deputy and the office includes additional staff.','distributed_creation','primary_record','unreviewed',NULL,'Leads an office with a deputy and staff.','No sole labor or sole authorship of office output.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_jal10_c07',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='josephus-allmond' LIMIT 1),'prior_legal_role','Allmond previously worked at SELC on utility-regulatory, solar and environmental-justice matters.','formal_role','corroborated','unreviewed',NULL,'Former SELC attorney with Virginia utility-regulatory experience.','No attribution of all SELC matters or results to him.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_jal10_c08',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='josephus-allmond' LIMIT 1),'commission_role','Allmond served as a citizen member of CEUR before entering the cabinet.','formal_role','primary_record','unreviewed',NULL,'Former citizen member of CEUR.','No sole commission authority or ownership of commission work.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_jal10_c09',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='josephus-allmond' LIMIT 1),'regulatory_engagement','The office has filed comments and letters in named SCC and PJM matters since the appointment.','institutional_output','primary_record','unreviewed',NULL,'The office has engaged in named regulatory proceedings.','No final victory, rate savings or causal performance absent decisions and measurement.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_jal10_c10',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='josephus-allmond' LIMIT 1),'claim_restriction','No reviewed public record establishes Allmond employment terms, compensation, budget authority, unilateral agency control, personal ownership, sole authorship, quantified attributable savings or psychology.','claim_restriction','observed','unreviewed',NULL,'Those domains remain unverified or incomplete.','Absence of public evidence is not evidence of absence.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)
